#
# [3518] Smallest Palindromic Rearrangement II 
#
from collections import Counter
import math
# @lc code=start
class Solution:
    def smallestPalindrome(self, s: str, k: int) -> str:
        n = len(s)
        halfN = n//2
        c = Counter(s[:halfN])

        numerator = math.factorial(halfN)
        denominator = 1
        for char in sorted(c):
            denominator *= math.factorial(c[char])
        
        if numerator // denominator < k:
            return ""

        pos = 0
        parsed = 0
        res = ""
        while pos < halfN:
            numerator = numerator // (halfN - pos)
            for char in sorted(c):
                if c[char] != 0:
                    numPermutations = numerator // (denominator // c[char])
                    if parsed+numPermutations < k:
                        parsed += numPermutations
                    else:
                        denominator = denominator // c[char]
                        c[char] -= 1
                        res = res + char
                        break
            pos += 1
        res = res + (s[halfN] if n % 2 == 1 else '') + res[::-1]
        return res

# @lc code=end
def main():
    s = Solution()
    string = ""
    k = 927815
    # res = s.smallestPalindrome("abadedaba", 7)
    res = s.smallestPalindrome(string, k)
    print(res)


if __name__ == '__main__':
    main()